#!/usr/bin/env bash
# Recrea la base de pruebas local y corre migraciones + pruebas SQL.
set -euo pipefail
DIR="$(cd "$(dirname "$0")/.." && pwd)"
su postgres -c "psql -q -c 'drop database if exists transporte_test' -c 'create database transporte_test'" 2>/dev/null
for f in tests/00_stub_auth.sql migrations/0001_core.sql migrations/0002_save_functions.sql migrations/0003_route_catalog.sql migrations/0004_route_ownership.sql migrations/0005_service_departures.sql migrations/0006_places_and_paths.sql migrations/0007_day_types_and_start_service.sql migrations/0008_route_times.sql migrations/0009_seat_classes_and_vehicle_kinds.sql migrations/0010_delete_seat_layout.sql migrations/0011_service_delete_and_date.sql migrations/0012_test_ticket_scan_override.sql migrations/0013_trip_takeover_reopen.sql migrations/0014_live_trip_positions.sql migrations/0015_live_trip_schedule.sql migrations/0016_route_maneuvers.sql migrations/0017_automatic_trip_advance.sql migrations/0018_sales_module.sql migrations/0019_sales_hardening.sql migrations/0020_passenger_portal.sql migrations/0021_public_trip_seat_layout.sql migrations/0022_mercadopago_checkout.sql migrations/0023_fix_checkout_status_ambiguity.sql migrations/0024_passenger_city_search.sql migrations/0025_normalize_seat_class_fares.sql migrations/0026_group_passenger_checkout.sql migrations/0027_passenger_company_directory.sql migrations/0028_company_logo_staff_permissions.sql migrations/0029_public_company_trip_browse.sql migrations/0030_company_feature_blocks.sql tests/01_core_test.sql tests/02_save_test.sql tests/03_catalog_test.sql tests/04_start_service_test.sql tests/05_route_times_test.sql tests/06_layout_delete_test.sql tests/07_service_delete_test.sql tests/08_test_ticket_scan_override_test.sql tests/09_trip_takeover_test.sql tests/10_live_trip_positions_test.sql tests/11_route_maneuvers_test.sql tests/12_automatic_trip_advance_test.sql tests/13_sales_hardening_test.sql tests/14_mercadopago_checkout_test.sql tests/15_checkout_status_test.sql tests/16_passenger_city_search_test.sql tests/17_group_passenger_checkout_test.sql tests/18_passenger_company_directory_test.sql tests/19_company_logo_permissions_test.sql tests/20_public_company_trip_browse_test.sql tests/21_company_feature_blocks_test.sql migrations/0031_taquilla_block_and_holds.sql migrations/0032_taquilla_seat_limit.sql migrations/0033_generate_publish_trips.sql migrations/0034_apply_price_to_all.sql migrations/0035_soft_delete_companies_services.sql migrations/0036_legajo_messages_incidents.sql migrations/0037_ventanilla.sql migrations/0038_service_assigned_vehicles.sql migrations/0039_advance_on_arrival.sql migrations/0040_advance_keeps_current_vehicle.sql migrations/0041_manual_boarding_by_dni.sql tests/22_taquilla_block_and_holds_test.sql tests/23_generate_publish_trips_test.sql tests/24_apply_price_to_all_test.sql tests/25_soft_delete_test.sql tests/26_legajo_messages_test.sql tests/27_ventanilla_test.sql tests/28_assigned_vehicle_test.sql tests/29_advance_on_arrival_test.sql tests/30_advance_keeps_vehicle_test.sql tests/31_manual_boarding_test.sql; do
  if ! output="$(su postgres -c "psql -q -v ON_ERROR_STOP=1 -t -A -d transporte_test -f $DIR/$f" 2>&1)"; then
    printf '%s\n' "$output"
    exit 1
  fi
  printf '%s\n' "$output" | grep -E 'ERROR|FALLA|PASARON|CONTEXT' || true
done
